#include <flint/fmpq.h>
#include <flint/fmpq_mpoly.h>
#include <flint/fmpq_mpoly_factor.h>
#include <fstream>
#include <iostream>
#include <vector>
#include <string>
#include <cassert>
#include <chrono>
using namespace std;fmpq_mpoly_ctx_t ctx;
struct Poly{fmpq_mpoly_t p;Poly(){fmpq_mpoly_init(p,ctx);}Poly(const Poly&a):Poly(){fmpq_mpoly_set(p,a.p,ctx);}Poly(Poly&&a):Poly(){fmpq_mpoly_swap(p,a.p,ctx);}Poly&operator=(Poly a){fmpq_mpoly_swap(p,a.p,ctx);return *this;}~Poly(){fmpq_mpoly_clear(p,ctx);}};
void write(ostream&o,const Poly&a){fmpq_t q;fmpq_init(q);ulong ex[3];int n=fmpq_mpoly_length(a.p,ctx);o<<n;for(int i=0;i<n;i++){fmpq_mpoly_get_term_coeff_fmpq(q,a.p,i,ctx);fmpq_mpoly_get_term_exp_ui(ex,a.p,i,ctx);char*s=fmpq_get_str(nullptr,10,q);o<<' '<<s;for(ulong x:ex)o<<' '<<x;flint_free(s);}o<<'\n';fmpq_clear(q);}

struct Factor {Poly p;long exp;};
vector<Factor> facs;
void record(const Poly&p,long mult){if(!mult)return;assert(!fmpq_mpoly_is_zero(p.p,ctx));if(fmpq_mpoly_is_fmpq(p.p,ctx))return;fmpq_mpoly_factor_t f;fmpq_mpoly_factor_init(f,ctx);assert(fmpq_mpoly_factor(f,p.p,ctx));Poly expanded;assert(fmpq_mpoly_factor_expand(expanded.p,f,ctx));assert(fmpq_mpoly_equal(expanded.p,p.p,ctx));for(int i=0;i<fmpq_mpoly_factor_length(f,ctx);i++){Poly g;fmpq_mpoly_factor_get_base(g.p,f,i,ctx);fmpq_mpoly_make_monic(g.p,g.p,ctx);long e=mult*fmpq_mpoly_factor_get_exp_si(f,i,ctx);bool hit=false;for(auto &x:facs)if(fmpq_mpoly_equal(x.p.p,g.p,ctx)){x.exp+=e;hit=true;break;}if(!hit)facs.push_back(Factor{g,e});}fmpq_mpoly_factor_clear(f,ctx);}
void primitive(vector<vector<Poly>>&A){int n=A.size();Poly g,h,q;for(int pass=0;pass<2;pass++)for(int i=0;i<n;i++){fmpq_mpoly_zero(g.p,ctx);for(int j=0;j<n;j++){auto&v=pass?A[j][i]:A[i][j];assert(fmpq_mpoly_gcd(h.p,g.p,v.p,ctx));g=h;if(fmpq_mpoly_is_one(g.p,ctx))break;}assert(!fmpq_mpoly_is_zero(g.p,ctx));if(fmpq_mpoly_is_fmpq(g.p,ctx))continue;record(g,1);for(int j=0;j<n;j++){auto&v=pass?A[j][i]:A[i][j];assert(fmpq_mpoly_divides(q.p,v.p,g.p,ctx));v=q;}}}
void primitiveDet(vector<vector<Poly>> A){auto start=chrono::steady_clock::now();int stage=0;while(A.size()>1){primitive(A);int n=A.size(),bi=-1,bj=-1;long cost=10000000;for(int i=0;i<n;i++)for(int j=0;j<n;j++){int l=fmpq_mpoly_length(A[i][j].p,ctx);if(l&&l<cost){cost=l;bi=i;bj=j;}}assert(bi>=0);swap(A[0],A[bi]);for(auto&r:A)swap(r[0],r[bj]);record(A[0][0],-(n-2));vector<vector<Poly>>B(n-1,vector<Poly>(n-1));Poly x,y;for(int i=1;i<n;i++)for(int j=1;j<n;j++){fmpq_mpoly_mul(x.p,A[0][0].p,A[i][j].p,ctx);fmpq_mpoly_mul(y.p,A[i][0].p,A[0][j].p,ctx);fmpq_mpoly_sub(B[i-1][j-1].p,x.p,y.p,ctx);}A=std::move(B);long terms=0;for(auto&r:A)for(auto&p:r)terms+=fmpq_mpoly_length(p.p,ctx);cerr<<"STAGE "<<stage++<<" SIZE "<<A.size()<<" TERMS "<<terms<<" SEC "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';assert(chrono::duration<double>(chrono::steady_clock::now()-start).count()<100);}record(A[0][0],1);for(auto&f:facs)assert(f.exp>=0);}
int main(int argc,char**argv){assert(argc==4);fmpq_mpoly_ctx_init(ctx,3,ORD_LEX);{ifstream in(argv[1]);ofstream out(argv[2]);assert(in&&out);int n,m,kdim;in>>n>>m>>kdim;vector<vector<Poly>>A(n,vector<Poly>(m));fmpq_t q;fmpq_init(q);ulong ex[3];for(auto&r:A)for(auto&a:r){int l;in>>l;for(int k=0;k<l;k++){string s;in>>s>>ex[0]>>ex[1]>>ex[2];assert(!fmpq_set_str(q,s.c_str(),10));fmpq_canonicalise(q);fmpq_mpoly_push_term_fmpq_ui(a.p,q,ex,ctx);}fmpq_mpoly_sort_terms(a.p,ctx);fmpq_mpoly_combine_like_terms(a.p,ctx);}int count;in>>count;count=min(count,stoi(argv[3]));vector<Factor>first;for(int t=0;t<count;t++){vector<int>rows(kdim),cols(kdim);for(int&i:rows)in>>i;for(int&i:cols)in>>i;vector<vector<Poly>>B(kdim,vector<Poly>(kdim));for(int i=0;i<kdim;i++)for(int j=0;j<kdim;j++)B[i][j]=A[rows[i]][cols[j]];facs.clear();primitiveDet(B);out<<"MINOR "<<t<<" FACTORS "<<facs.size()<<'\n';for(auto&f:facs)if(f.exp){out<<"EXP "<<f.exp<<'\n';write(out,f.p);}if(t==0)first=facs;else{Poly cross;for(auto&x:first)if(x.exp)for(auto&y:facs)if(y.exp){assert(fmpq_mpoly_gcd(cross.p,x.p.p,y.p.p,ctx));if(!fmpq_mpoly_is_fmpq(cross.p,ctx)){out<<"CROSS_GCD\n";write(out,cross);}}}out.flush();assert(out.good());cerr<<"MINOR_PASS "<<t<<'\n';}fmpq_clear(q);facs.clear();}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
